  var testAds = false;
  function isTimeToPlayVideoAd() {
    if (G.productBlockAds || respawnVideoPlayed) {
      return false;
    }
    let timeout2 = adTest ? 3e4 : 24e4;
    if (pokiActive) timeout2 = 0;
    const adReady = hasTimesPlayed || timesPlayed > 1;
    const lastPreRoll = getStoredNumber("lastPreRoll", Date.now());
    const whenToPlay = lastPreRoll + timeout2;
    const timeForAd = adReady && deaths > 1 && Date.now() > whenToPlay;
    const metaTimeForAd = metaGameUI.timeToPlayVideoAd();
    if (metaTimeForAd !== null) {
      return metaTimeForAd;
    }
    if (timeForAd) {
      console.log("video ad cancels respawnBtn click");
      const respawnBtn = document.querySelector(".btn-respawn");
      respawnBtn.removeEventListener("click", respawnRequestPointerLock, { once: true });
    }
    return timeForAd;
  }
