  function createDynamicStampTexture(stampUrl) {
    return new Promise((resolve, reject) => {
      const canvas2 = document.createElement("canvas");
      canvas2.width = 4096;
      canvas2.height = 4096;
      const context = canvas2.getContext("2d");
      const stampImage = new Image();
      stampImage.src = stampUrl;
      stampImage.onload = () => {
        try {
          context.clearRect(0, 0, canvas2.width, canvas2.height);
          const shiftX = stampImage.width;
          const shiftY = 0;
          context.drawImage(stampImage, shiftX, shiftY, stampImage.width, stampImage.height);
          const textureDataURL = canvas2.toDataURL("image/png");
          resolve(textureDataURL);
        } catch (drawError) {
          console.error("Error drawing the stamp image:", drawError);
          reject(drawError);
        }
      };
      stampImage.onerror = (err) => {
        console.error("Failed to load stamp image:", stampUrl, err);
        reject(err);
      };
    });
  }
