    let stage;
    switch (item.item_type_id) {
      case ItemType2.Hat:
        stage = {
          radius: 1.4,
          rotation: new Vector3(-0.25, -2, 0),
          position: new Vector3(item.align.x * 0.5, item.align.y, item.align.z)
        };
        break;
      case ItemType2.Grenade:
        stage = {
          radius: 0.4,
          rotation: new Vector3(0, 1.3, 0),
          position: new Vector3(0, -0.01, 0)
        };
        break;
      case ItemType2.Melee:
        stage = {
          radius: 0.7,
          rotation: new Vector3(0.4, -3.8, -0.9),
          position: new Vector3(0, -0.05, 0.07)
        };
        break;
      case ItemType2.Primary:
        stage = {
          radius: 1.3,
          rotation: new Vector3(0.7, -0.02, 0)
        };
        switch (item.exclusive_for_class) {
          case CharClass.Soldier:
            stage.position = new Vector3(0, -0.18, 0.27);
            break;
          case CharClass.Eggsploder:
            stage.position = new Vector3(0, -0.15, 0.21);
            break;
          case CharClass.Scrambler:
            stage.position = new Vector3(0, -0.18, 0.27);
            break;
          case CharClass.Ranger:
            stage.position = new Vector3(0, -0.2, 0.26);
            break;
          case CharClass.Whipper:
            stage.position = new Vector3(0, -0.15, 0.22);
            break;
          case CharClass.Crackshot:
            stage.position = new Vector3(0, -0.16, 0.26);
            break;
          case CharClass.TriHard:
            stage.position = new Vector3(0, -0.16, 0.25);
            break;
          default:
            stage.position = new Vector3(0, -0.15, 0.25);
        }
        break;
      case ItemType2.Secondary:
        stage = {
          radius: 1,
          rotation: new Vector3(0, 0, 0),
          position: new Vector3(0, 0.05, 0.36)
        };
        break;
      default:
    }
    mesh.position.copyFrom(stage.position);
    mesh.rotation.copyFrom(stage.rotation);
    mesh.computeWorldMatrix(true);
    this.camera.position.x = stage.radius;
    this.camera.computeWorldMatrix();
    this.scene.render();
    mesh.dispose();
