    var ctx = destCanvas.getContext("2d");
    ctx.clearRect(0, 0, 256, 256);
    ctx.drawImage(this.canvas, (this.canvas.width - this.canvas.height) / 2, 0, this.canvas.height, this.canvas.height, 0, 0, 256, 256);
