  function listenForOneSignalNotifications() {
    OneSignal.push(["addListenerForNotificationOpened", function(notification) {
      console.log("Received NotificationOpened:");
      console.log(notification);
      let timestamp = Math.floor(Date.now() / 1e3);
      OneSignal.sendTag("last_notification_click", timestamp);
      if (notification.data !== void 0 && notification.data !== null) {
        console.log("data", notification.data);
        if (notification.data.notification_topic !== void 0 && notification.data.notification_topic !== null) {
          let notification_topic = notification.data.notification_topic;
          if (notification_topic) {
            OneSignal.getTags().then(function(tags) {
              var topicCount = parseInt(tags[notification_topic], 10);
              if (!isNaN(topicCount)) {
                topicCount += 1;
              } else {
                topicCount = 1;
              }
              OneSignal.sendTag(notification_topic, topicCount).then(function(tagsSent) {
                console.log("tagsSent: ", JSON.stringify(tagsSent));
              });
            });
          }
        }
        if (notification.data.nugget !== void 0) {
          showNugget = true;
          tryShowNugget();
          return;
        }
        if (notification.data.specialTagItems !== void 0) {
          tryShowTaggedItems(notification.data.specialTagItems);
          return;
        }
        if (notification.data.eggStorePopup !== void 0) {
          showProductPopup(notification.data.eggStorePopup);
          return;
        }
        if (notification.data.rewardTag !== void 0) {
          reward = new PlayerReward(
            notification.data.rewardTag,
            notification.data.rewardOpenUrl === void 0 ? null : notification.data.rewardOpenUrl,
            notification.data.rewardOpenUrlMsg === void 0 ? null : notification.data.rewardOpenUrlMsg
          );
          if (isRunning === true) {
            tryGiveOneSignalReward();
          }
        }
      }
    }]);
  }
