  var Product = class {
    constructor() {
      this.categories = {
        currency: [],
        item: [],
        subscription: [],
        pass: [],
        bundle: []
      };
      this.initialized = false;
      this.welcomeBundleItemId = welcomePassItemId;
    }
    // Initialize product categories
    init() {
      if (!SsProducts || !Array.isArray(SsProducts)) {
        console.log("No products");
        return;
      }
      Object.keys(this.categories).forEach((type) => {
        this.categories[type] = SsProducts.filter((pro) => pro.type === type);
      });
      this.initialized = true;
    }
    // Helper to validate initialization
    isInitialized() {
      if (!this.initialized) {
        console.warn("Product class not initialized.");
        return false;
      }
      return true;
    }
    // Get products by SKU
    getBySku(sku) {
      if (!this.isInitialized()) return;
      return SsProducts.find((pro) => pro.sku === sku) || null;
    }
    // Get shop items
    getShopItems() {
      if (!this.isInitialized()) return [];
      return this.categories.item.filter((pro) => pro.isActive);
    }
    // only show te pass if the player does not own it
    // otherwise show the bundle
    storeItemsFilterPassBundle(products) {
      const passItem = G.catalog.findItemById(welcomePassItemId);
      if (!passItem) return products.filter((pro) => pro.type !== "pass");
      const passOwned = G.playerAccount.isItemOwned(passItem);
      if (!passOwned) {
        return products.filter((el) => el.id !== 1);
        ;
      } else {
        return products.filter((pro) => pro.type !== "pass");
      }
    }
    // Get store items
    getStoreItems() {
      if (!this.isInitialized()) return [];
      const availableProducts = SsProducts.filter((pro) => pro.inStore && pro.isActive);
      if (!availableProducts.length) return [];
      if (this.categories.pass.length > 0) {
        return this.storeItemsFilterPassBundle(availableProducts);
      }
      return availableProducts;
    }
    // Get active subscriptions
    getSubscriptions() {
      return this.getActiveByType("subscription");
    }
    // Get active bundles
    getBundles() {
      return this.getActiveByType("bundle");
    }
    // Get active products by type
    getActiveByType(type) {
      if (!this.isInitialized()) return [];
      return this.categories[type]?.filter((pro) => pro.isActive) || [];
    }
    // Get bundles by item ID
    getBundlesByItemId(itemIds) {
      return this.getBundles().filter((bundle) => this.matchItemIds(bundle.itemIds, itemIds));
    }
    // Get passes by item ID
    getPassByItemId(itemIds) {
      return this.categories.pass.filter((pass) => this.matchItemIds(pass.itemIds, itemIds));
    }
    // Get product by type and item IDs
    getProductByItemIds(type, itemIds) {
      if (!this.isInitialized() || !this.categories[type]) return [];
      return this.categories[type].filter((product) => this.matchItemIds(product.itemIds, itemIds));
    }
    // Check if item IDs match
    matchItemIds(itemIds, compareArr) {
      if (!Array.isArray(itemIds) || !Array.isArray(compareArr) || itemIds.length !== compareArr.length) {
        return false;
      }
      return itemIds.every((id, index) => id === compareArr[index]);
    }
    // Get product type by SKU
    getProductType(sku) {
      const product = this.getBySku(sku);
      return product?.type || null;
    }
    // Get product title by egg value
    getProductTitleByEggValue(value) {
      if (!this.isInitialized()) return null;
      const product = this.categories.currency.find((pro) => pro.currency === value);
      return product?.sku || null;
    }
  };
  var ReliableWebSocket = class {
    constructor(url) {
      this.url = url;
      this.ws = null;
      this.queue = [];
      this.reconnectTimeout = null;
      this.reconnectTimeoutTime = 0;
      this.pingInterval = null;
      this.connect(url);
    }
    connect() {
      if (this.ws && (this.ws.readyState === WebSocket.CONNECTING || this.ws.readyState === WebSocket.OPEN)) {
        return;
      }
      console.log(`ReliableWebSocket: Connecting to ${this.url}`);
      try {
        this.ws = new WebSocket(this.url);
      } catch (e) {
        this._onerror(e);
        return;
      }
      this.ws.onopen = () => {
        console.log(`ReliableWebSocket: Connected to ${this.url}`);
        this.reconnectTimeoutTime = 0;
        this.queue.forEach((message) => {
          this.ws.send(message);
        });
        this.queue = [];
        this.pingInterval = setInterval(() => {
          this.ws.send("ping");
        }, 3e4);
        this.onopen();
      };
      this.ws.onclose = (e) => {
        console.log(`ReliableWebSocket: Disconnected from ${this.url} with code ${e.code} - Attempting to reconnect in ${this.reconnectTimeoutTime} seconds...`);
        clearInterval(this.pingInterval);
        if (e.code !== CloseCode.NORMAL_CLOSURE && !this.reconnectTimeout) {
          this.reconnectTimeout = setTimeout(() => {
            this.reconnectTimeout = null;
            this.connect();
          }, this.reconnectTimeoutTime * 1e3);
          this.reconnectTimeoutTime = Math.min(this.reconnectTimeoutTime + 1, 10);
        }
        this.onclose(e);
      };
      this.ws.onerror = (e) => this._onerror(e);
      this.ws.onmessage = (e) => this.onmessage(e);
    }
    send(message) {
      if (this.ws.readyState === WebSocket.OPEN) {
        this.ws.send(message);
      } else {
        this.queue.push(message);
        if (this.ws.readyState !== WebSocket.CONNECTING) {
          this.connect();
        }
      }
    }
    _onerror(e) {
      if (this.reconnectTimeoutTime > 4) {
        this.queue = [];
        this.onerror(e);
      }
    }
    onopen() {
    }
    onclose(e) {
    }
    onmessage(e) {
    }
    onerror(e) {
    }
  };
